-- File: 07-decide-appeal.sql
-- Purpose: admin 裁決賣家對 violation 的申訴（accept / reject）；accept 時同步 revoke violation + 還原 sellers.status
-- When to use: admin UI 故障時，admin 直接裁決申訴
-- Variables to fill:
--   :violation_id   — 被申訴的 seller_violations.id
--   :decision       — 'accepted' / 'rejected'
--   :decision_reason— 裁決理由（賣家可看到）
--   :admin_id       — 裁決 admin id
-- Audit: 執行後將完整 SQL + 結果貼到 Discord #food-safety-actions channel 留紀錄
-- Generated by B-169 (issue #722) — 2026-05-07
--
-- 前提：該 violation.appealed=true、appeal_status='pending'、appeal_submitted_at IS NOT NULL
-- 流程：
--   (1) accept：appeal_status='accepted' + violation.status='revoked' + revoked_reason='appeal_accepted'
--       若 penalty_type='full_suspension' → 還原 sellers.status='active'
--   (2) reject：僅更新 appeal_status='rejected'，violation 與 sellers 不變

BEGIN;

-- 0. 先確認該 violation 確實在 pending 申訴中
SELECT
    id, seller_id, penalty_type, severity,
    status, expires_at,
    appealed, appeal_status, appeal_submitted_at,
    LEFT(appeal_reason, 100) AS appeal_reason_preview
FROM seller_violations
WHERE id = :violation_id;
-- 若 appeal_status 不是 'pending' 請 ROLLBACK 並調整變數

-- 1. 更新 appeal_status / appeal_decision_reason / appeal_decided_*
UPDATE seller_violations
SET
    appeal_status = :'decision',
    appeal_decision_reason = :'decision_reason',
    appeal_decided_at = now(),
    appeal_decided_by_admin_id = :admin_id,
    -- 若 accept：同時 revoke violation
    status = CASE
        WHEN :'decision' = 'accepted' THEN 'revoked'
        ELSE status
    END,
    revoked_at = CASE
        WHEN :'decision' = 'accepted' AND revoked_at IS NULL THEN now()
        ELSE revoked_at
    END,
    revoked_reason = CASE
        WHEN :'decision' = 'accepted' THEN 'appeal_accepted'
        ELSE revoked_reason
    END,
    updated_at = now()
WHERE id = :violation_id
  AND appealed = true
  AND appeal_status = 'pending'
RETURNING
    id, seller_id, penalty_type, status,
    revoked_at, revoked_reason,
    appeal_status, appeal_decided_at, appeal_decided_by_admin_id;

-- 2. 若 accept 且 penalty_type='full_suspension' → 還原 sellers.status
--    用 sub-select 確認 penalty_type；若是 reject 或非停權處分，WHERE 不會命中、no-op
UPDATE sellers
SET
    status = 'active',
    updated_at = now()
WHERE account_id = (
        SELECT seller_id
        FROM seller_violations
        WHERE id = :violation_id
          AND penalty_type = 'full_suspension'
      )
  AND :'decision' = 'accepted'
  AND status = 'suspended_governance'
RETURNING account_id, status, updated_at;

-- 3. 驗證：完整最終狀態
SELECT
    sv.id              AS violation_id,
    sv.seller_id,
    sv.penalty_type,
    sv.status          AS violation_status,
    sv.revoked_at,
    sv.revoked_reason,
    sv.appeal_status,
    sv.appeal_decision_reason,
    sv.appeal_decided_at,
    sv.appeal_decided_by_admin_id,
    s.status           AS seller_status
FROM seller_violations sv
JOIN sellers s ON s.account_id = sv.seller_id
WHERE sv.id = :violation_id;

-- 預期：
--   accept + full_suspension : violation_status='revoked', appeal_status='accepted', seller_status='active'
--   accept + 其他            : violation_status='revoked', appeal_status='accepted', seller_status 不變
--   reject                   : violation_status 不變,      appeal_status='rejected',  seller_status 不變
ROLLBACK; -- 確認後改 COMMIT;
